function Config.StarTowerData.data_get_floor_award_fun(slot0)
	slot1 = Config.StarTowerData.data_get_floor_award[slot0]

	if DATA_DEBUG and slot1 == nil then
		print("(Config.StarTowerData.data_get_floor_award[" .. slot0 .. "])not found")

		return
	end

	return slot1
end
